insert into posts (id, author_id, circle_id, citation_count, city, comment_count, content, created_at, destination, favorite_count, images, like_count, mode_tag, status, title, trusted_badge, type, view_count, cost_per_person, days, avoid_tags, suitable_for) values
(1,2,5,12,'长沙',2,'Day1 岳麓山爱晚亭→湖南博物院→五一广场→太平街；Day2 橘子洲→超级文和友→坡子街火宫殿。全程地铁可达，博物院记得提前7天预约，晚上的橘子洲灯光秀别错过。附避坑：火车站附近拉客的一日游不要报！','2026-10-03 10:30:00','长沙市区',45,'/images/p_changsha_cw.jpg',3,'LEISURE','APPROVED','长沙两日Citywalk完全攻略｜本地人路线不踩雷',0x00,'GUIDE',865,NULL,NULL,NULL,NULL),
(2,2,2,21,'张家界',2,'三天路线：D1金鞭溪-袁家界阿凡达山；D2天子山看日出后下山；D3天门山玻璃栈道。时间充裕可加老道湾野线，但必须请向导、结伴而行，切勿独行。门票和索道都要提前在公众号抢。','2026-10-02 10:30:00','武陵源-天门山',88,'/images/p_zjj_trek.jpg',158,'WILD','APPROVED','张家界三天两夜徒步路线｜森林公园+天门山+老道湾',0x00,'GUIDE',1204,NULL,NULL,NULL,NULL),
(3,3,3,1,'重庆',1,'晚上7点半洪崖洞准时亮灯，千厮门大桥上的机位最绝。拍完坐长江索道过江，重庆的夜景真的怎么拍都出片。','2026-10-02 10:30:00','洪崖洞',12,'/images/p_cq_night.jpg',52,NULL,'APPROVED','重庆山城夜游随手拍，洪崖洞亮灯瞬间封神',0x00,'MOMENT',432,NULL,NULL,NULL,NULL),
(4,4,1,6,'成都',2,'宽窄巷子主街偏贵，要吃请转进旁边的奎星楼街：冒椒火辣、二娘鸡爪、严太婆锅盔。三大炮5块钱尝个热闹就行，真正的老成都味道在巷子里的茶馆和苍蝇馆子。','2026-10-01 10:30:00','宽窄巷子-奎星楼',60,'/images/p_cd_food.jpg',88,'FOOD','APPROVED','成都本地人带你吃宽窄巷子｜这几家店游客真不知道',0x01,'LOCAL',756,NULL,NULL,NULL,NULL),
(5,2,6,9,'西安',2,'早上8点城墙南门骑行一圈（约100分钟），中午永兴坊吃biangbiang面，下午陕西历史博物馆，晚上大唐不夜城看不倒翁小姐姐。一天3万步，穿最舒服的鞋！','2026-10-01 10:30:00','西安城墙-大唐不夜城',33,'/images/p_xian_wall.jpg',120,'SPEED','APPROVED','西安特种兵一日速通｜城墙骑行到大唐不夜城',0x00,'GUIDE',980,NULL,NULL,NULL,NULL),
(6,3,3,0,'厦门',0,'避开人群往岛的西侧走，鼓声洞旁边的礁石滩几乎没人，海风、老别墅和猫，适合带一本书坐一下午。','2026-09-30 10:30:00','鼓浪屿',20,'/images/p_xm_sea.jpg',41,NULL,'APPROVED','鼓浪屿看海的下午，时间都慢下来了',0x00,'MOMENT',355,NULL,NULL,NULL,NULL),
(7,4,1,4,'长沙',1,'火宫殿晚上比白天热闹，臭豆腐去黑色经典，糖油粑粑要趁热吃。太平街的贾谊故居免费参观，逛吃顺序建议：先太平街再坡子街，一路吃过去不用走回头路。','2026-09-30 10:30:00','坡子街-太平街',51,'/images/p_cs_pozi.jpg',77,'FOOD','APPROVED','长沙土著私藏的坡子街正确打开方式',0x01,'LOCAL',640,NULL,NULL,NULL,NULL),
(8,2,6,18,'重庆',2,'李子坝穿楼建议下午去，顺光好拍；长江索道提前在公众号买票能省1小时排队；山城步道比洪崖洞更有老重庆味道，而且免费！导航在重庆会骗人，多问路人。','2026-09-29 10:30:00','渝中半岛',70,'/images/p_cq_train.jpg',143,'OPTIMAL','APPROVED','重庆魔幻8D交通避坑指南｜轻轨索道这么坐',0x00,'GUIDE',1102,NULL,NULL,NULL,NULL),
(9,3,2,0,'张家界',1,'计划10月2号到4号去，想问下森林公园门票和天门山索道票分别要提前几天抢？现场买得到吗？求各位大佬指点。','2026-09-29 10:30:00','武陵源',2,'/images/p_zjj_queue.jpg',8,NULL,'APPROVED','十一去张家界需要提前订票吗？求本地人解答',0x00,'QUESTION',210,NULL,NULL,NULL,NULL),
(10,4,5,3,'成都',1,'不赶时间版本：D1宽窄巷子+人民公园鹤鸣茶社；D2大熊猫基地（一定赶早！）+建设路小吃；D3锦里武侯祠+蜀大侠火锅。成都就适合慢悠悠地晃。','2026-09-28 10:30:00','成都市区',34,'/images/p_cd_tea.jpg',61,'LEISURE','APPROVED','成都慢生活三日休闲路线｜喝茶看熊猫吃火锅',0x00,'GUIDE',530,NULL,NULL,NULL,NULL),
(11,2,2,0,'长沙',0,'听说岳麓山后山有条野路上山，想周末去试试，有没有走过的同学说说路况和注意事项？一个人有点虚。','2026-09-28 10:30:00','岳麓山后山',5,'/images/p_yelu_wild.jpg',15,'WILD','APPROVED','岳麓山野线有没有同行过的？一个人敢走吗',0x00,'QUESTION',188,NULL,NULL,NULL,NULL),
(12,3,3,1,'西安',1,'街上全是穿汉服的小姐姐，仿佛一秒穿越回盛唐。建议提前在附近租好妆造，晚上8点有演出巡游。','2026-10-04 10:30:00','大唐不夜城',14,'/images/p_dt_buye.jpg',55,NULL,'APPROVED','大唐不夜城夜景yyds，汉服拍照太出片',0x00,'MOMENT',470,NULL,NULL,NULL,NULL),
(13,4,2,0,'张家界',0,'本地人手把手教：A线索道上、环保车下最省力；玻璃栈道鞋套5元；天门洞999级台阶下比上轻松，但膝盖不好建议坐扶梯。山顶温差大记得带外套。','2026-10-04 10:30:00','天门山',0,'/images/p_tms.jpg',0,NULL,'PENDING','张家界本地向导教你玩天门山｜999级天梯这样爬省力',0x01,'LOCAL',0,NULL,NULL,NULL,NULL),
(14,2,5,0,'成都',0,'九点之后熊猫基本都进屋睡觉了，八点半入园冲幼年别墅，能看到活跃到模糊的团子们！','2026-10-04 10:30:00','大熊猫基地',0,'/images/p_panda.jpg',0,NULL,'PENDING','看大熊猫的正确时间：早上八点半，没有之一',0x00,'MOMENT',0,NULL,NULL,NULL,NULL),
(15,14,5,6,'长沙',33,'长沙两日Citywalk路线，实测走下来体力消耗中等，路上补给点不少。建议早上出发避开人流，穿轻便鞋，带够水和防晒。学生证记得带着，不少地方能免票或半价。路线已经存到我的路线夹，需要的同学可以直接拿去用。','2026-10-04 11:37:00','长沙',60,'/images/p_xm_sea.jpg',147,'CITYWALK','APPROVED','长沙两日Citywalk路线｜不走回头路的本地玩法',0x00,'GUIDE',874,NULL,NULL,NULL,NULL),
(16,9,2,54,'长沙',47,'岳麓山+橘子洲一日徒步，实测走下来体力消耗中等，路上补给点不少。建议早上出发避开人流，穿轻便鞋，带够水和防晒。学生证记得带着，不少地方能免票或半价。路线已经存到我的路线夹，需要的同学可以直接拿去用。','2026-10-04 13:32:00','长沙',153,'/images/p_dt_buye.jpg,/images/p_yelu_wild.jpg',294,'SCENIC','APPROVED','岳麓山+橘子洲一日徒步｜从爱晚亭走到橘子洲头',0x00,'GUIDE',2301,NULL,NULL,NULL,NULL),
(17,3,1,41,'长沙',107,'长沙美食避坑指南，实测走下来体力消耗中等，路上补给点不少。建议早上出发避开人流，穿轻便鞋，带够水和防晒。学生证记得带着，不少地方能免票或半价。路线已经存到我的路线夹，需要的同学可以直接拿去用。','2026-10-04 22:30:00','长沙',211,'/images/p_cd_tea.jpg,/images/p_zjj_queue.jpg,/images/p_cq_train.jpg',467,'FOOD','APPROVED','长沙美食避坑指南｜这些店学生党真的能吃',0x01,'GUIDE',2385,NULL,NULL,NULL,NULL),
(18,14,3,7,'长沙',8,'五一广场夜景实拍，实测走下来体力消耗中等，路上补给点不少。建议早上出发避开人流，穿轻便鞋，带够水和防晒。学生证记得带着，不少地方能免票或半价。路线已经存到我的路线夹，需要的同学可以直接拿去用。','2026-10-04 19:55:00','长沙',29,'/images/p_yelu_wild.jpg,/images/p_dt_buye.jpg',125,'PHOTO','APPROVED','五一广场夜景实拍｜长沙的赛博朋克味出来了',0x00,'MOMENT',1404,NULL,NULL,NULL,NULL),
