insert into product_reviews (id, avatar, content, created_at, merchant_id, nickname, order_id, product_id, product_name, rating, replied_at, reply, user_id) values
(1,'/images/av_dao.jpg','背包做工扎实，承重很稳，周末武功山三天下来肩膀没怎么酸，学长发货也快。','2026-10-06 18:25:12',1,'驼子',1,8,'316不锈钢保温杯500ml',5,'2026-10-09 18:25:12','感谢支持！记得把腰带调到胯部位置，能省不少力气～',10),
