insert into spots (id, category, city, description, heat, image, lat, lng, name) values
(1,'NATURE','长沙','中国四大名亭之一，岳麓山半山腰，秋季红枫环绕，毛泽东青年时代常来此读书锻炼。',92,'/images/s_awt.jpg',28.1835,112.9345,'岳麓山爱晚亭'),
(2,'HISTORY','长沙','湘江中心的长岛，青年毛泽东艺术雕塑所在地，每周六晚有烟花与灯光秀。',98,'/images/s_jzz.jpg',28.19,112.968,'橘子洲'),
(3,'HISTORY','长沙','马王堆汉墓素纱襌衣、T型帛画的家，国家一级博物馆，需提前预约。',85,'/images/s_museum.jpg',28.21,112.9915,'湖南博物院'),
(4,'TRENDY','长沙','复古怀旧风楼内街景，小龙虾与老长沙小吃，拍照与排队同样出名。',90,'/images/s_why.jpg',28.1905,112.9735,'超级文和友'),
(5,'FOOD','长沙','长沙美食地标，臭豆腐、糖油粑粑、口味虾一站式打卡。',88,'/images/s_hgd.jpg',28.1935,112.972,'坡子街火宫殿'),
(6,'SECRET','长沙','后山未开发野路，坡陡林密，有迷路与滑坠风险，务必结伴报备。',62,'/images/s_yl_wild.jpg',28.1815,112.925,'岳麓山野路'),
(7,'THEME','长沙','大型主题乐园，过山车、摩天轮与节日活动，适合结伴玩一整天。',70,'/images/s_window.jpg',28.236,113.042,'长沙世界之窗'),
(8,'TRENDY','长沙','长沙最繁华商圈，IFS楼顶KAWS雕塑与黄兴路步行街都在这里。',95,'/images/s_wuyi.jpg',28.1975,112.979,'五一广场'),
(9,'FOOD','长沙','保留青石板路的历史老街，贾谊故居与各色特色小店云集。',82,'/images/s_taiping.jpg',28.1965,112.9725,'太平街'),
(10,'NATURE','长沙','大片花海、水杉林与樱花湖，春有樱花秋有彩林，免费预约入园。',68,'/images/s_botany.jpg',28.145,113.035,'湖南省森林植物园'),
(11,'NATURE','张家界','中国第一个国家森林公园，石英砂岩峰林地貌，金鞭溪与袁家界核心景区。',96,'/images/s_forest.jpg',29.325,110.435,'张家界国家森林公园'),
(12,'NATURE','张家界','湘西第一神山，999级上天梯通向天门洞，山顶玻璃栈道闻名全国。',94,'/images/s_tianmen.jpg',29.048,110.482,'天门山'),
(13,'TRENDY','张家界','悬于海拔1400米绝壁上的透明步道，脚下即是深渊，胆勇者的打卡地。',91,'/images/s_glass.jpg',29.052,110.483,'天门山玻璃栈道'),
(14,'SECRET','张家界','未开发原始山谷野线，溪流密林与碎石坡，高风险，必须请持证向导。',58,'/images/s_laodao.jpg',29.021,110.503,'老道湾野线'),
(15,'TRENDY','重庆','十一层吊脚楼建筑群，夜景神似千与千寻，重庆第一打卡地标。',93,'/images/s_hyd.jpg',29.563,106.5836,'洪崖洞'),
(16,'TRENDY','重庆','横跨长江的空中公交车，俯瞰两江四岸立体山城，建议线上提前购票。',80,'/images/s_cable.jpg',29.555,106.587,'长江索道'),
(17,'TRENDY','重庆','2号线列车从居民楼中穿过，8D魔幻交通的代表作，楼下有专用观景台。',86,'/images/s_liziba.jpg',29.557,106.547,'李子坝轻轨穿楼'),
(18,'SECRET','重庆','悬崖上的老石阶步道，老重庆民居与江景并存，游客稀少的宝藏路线。',64,'/images/s_shancheng.jpg',29.553,106.566,'山城步道'),
(19,'HISTORY','成都','清代古街区，由宽巷子、窄巷子和井巷子组成，茶馆与川西民居风情。',84,'/images/s_kz.jpg',30.67,104.06,'宽窄巷子'),
(20,'THEME','成都','距离市区最近的熊猫家园，赶早入园才能看到干饭活跃的团子。',90,'/images/s_panda_base.jpg',30.7335,104.1455,'大熊猫繁育研究基地'),
(21,'THEME','西安','盛唐主题步行街，灯火辉煌、演出不断，不倒翁小姐姐就在这里。',92,'/images/s_dt.jpg',34.218,108.959,'大唐不夜城'),
(22,'HISTORY','西安','中国现存最完整的古代城垣，可租自行车骑行一圈，俯瞰老城街巷。',87,'/images/s_citywall.jpg',34.259,108.947,'西安城墙'),
(23,'TRENDY','长沙','扎哈设计的白色流线建筑群，临湖拍照极出片，周边有商场与剧院。',74,NULL,28.198,112.902,'梅溪湖文化艺术中心'),
(24,'FOOD','长沙','藏在太平街旁边的安静老街，老长沙小吃与茶馆并存，游客相对少。',72,NULL,28.19,112.977,'都正街'),
(25,'NATURE','长沙','城市南端的大片湿地，芦苇丛与水杉林适合骑行散步，全年免费开放。',70,NULL,28.112,112.91,'洋湖湿地公园'),
(26,'NATURE','张家界','《阿凡达》悬浮山原型所在地，乾坤柱与天下第一桥是核心看点，云雾天最美。',95,NULL,29.36,110.43,'袁家界'),
(27,'NATURE','张家界','峰林观景台群，云海翻涌时如入仙境，索道与环保车衔接方便。',90,NULL,29.39,110.44,'天子山'),
(28,'NATURE','张家界','高峡出平湖，坐船穿行于峰壁之间，还能听土家山歌对唱。',76,NULL,29.34,110.48,'宝峰湖'),
(29,'TRENDY','重庆','重庆最繁华的商圈与城市原点，周围火锅小面密集，夜里灯火通明。',90,NULL,29.558,106.576,'解放碑步行街'),
(30,'HISTORY','重庆','嘉陵江边的千年古镇，青石板路配吊脚楼，陈麻花现做现卖。',82,NULL,29.585,106.444,'磁器口古镇'),
(31,'TRENDY','重庆','俯瞰渝中半岛的最佳机位，日落前后半小时到夜景初上最出片。',87,NULL,29.529,106.584,'南山一棵树观景台'),
(32,'TRENDY','重庆','老厂房改造的文创园区，涂鸦墙与天台视角俱佳，年轻人扎堆。',78,NULL,29.549,106.556,'鹅岭二厂文创公园'),
(33,'NATURE','重庆','喀斯特天坑与天生桥群，《满城尽带黄金甲》取景地，从主城出发需一整天。',89,NULL,29.471,107.543,'武隆天生三桥'),
(34,'SECRET','重庆','没有电梯的魔幻居民楼，多部电影取景地，楼道窗口能拍到过江索道。',72,NULL,29.559,106.581,'白象居'),
(35,'HISTORY','成都','紧邻武侯祠的川西古镇街区，入夜红灯笼亮起最有味道，小吃与手作店密集。',86,NULL,30.6471,104.0437,'锦里古街'),
(36,'HISTORY','成都','纪念诸葛亮与刘备的君臣合祀祠庙，三顾茅庐与出师表石刻都在这里。',83,NULL,30.6485,104.0435,'武侯祠'),
(37,'HISTORY','成都','诗圣杜甫寓居成都的故居，竹林清幽，是市区里难得的安静园林。',81,NULL,30.6585,104.028,'杜甫草堂'),
(38,'FOOD','成都','成都最老的茶馆之一，竹椅盖碗茶配掏耳朵，体验本地人的松弛日常。',88,NULL,30.658,104.063,'人民公园鹤鸣茶社'),
(39,'TRENDY','成都','成都最时尚的商圈，大慈寺与玻璃幕墙共存，街拍与逛街两不误。',90,NULL,30.653,104.081,'春熙路太古里'),
(40,'NATURE','成都','道教发源地之一，山幽林密、湿润清凉，前山宫观集中、后山野趣更足。',79,NULL,30.902,103.573,'青城山'),
(41,'NATURE','成都','两千多年仍在服役的水利工程，鱼嘴分水、飞沙堰排沙，强烈建议请讲解。',85,NULL,31.002,103.619,'都江堰景区'),
(42,'HISTORY','西安','世界第八大奇迹，一号坑军阵最震撼，务必提前网上购票并请讲解。',97,NULL,34.385,109.273,'秦始皇兵马俑'),
(43,'HISTORY','西安','骊山脚下的唐代离宫，温泉汤池与西安事变旧址同在，《长恨歌》演出有名。',84,NULL,34.36,109.22,'华清宫'),
(44,'HISTORY','西安','玄奘译经藏经之地，塔身七层可登，北广场音乐喷泉晚上人最多。',86,NULL,34.218,108.964,'大雁塔'),
(45,'HISTORY','西安','周秦汉唐文物大观，何家村窖藏金银器必看，需提前预约且常常约满。',88,NULL,34.228,108.95,'陕西历史博物馆'),
(46,'FOOD','西安','钟鼓楼旁的美食街，肉夹馍、羊肉泡馍、酸梅汤一条街吃到撑。',85,NULL,34.265,108.933,'回民街'),
(47,'THEME','西安','仿唐皇家园林，水幕电影与夜间演出很出片，适合傍晚进场一直待到亮灯。',80,NULL,34.213,108.97,'大唐芙蓉园'),
(48,'NATURE','西安','五岳之险，长空栈道与鹞子翻身惊险出名，夜爬看日出请结伴并备足体力。',92,NULL,34.49,110.085,'华山'),
(49,'HISTORY','长沙','湘江东岸的仿唐楼阁，为纪念杜甫而建，与橘子洲隔江相望，夜晚亮灯后适合江边散步拍照。',80,NULL,28.187,112.9707,'杜甫江阁'),
