-- 学旅圈数据库脚本（xlvq 库）


-- 1. 创建数据库
create database if not exists xlvq default character set utf8;

use xlvq;

-- 2. 广告表（ads）

drop table if exists ads;
create table ads (
    id bigint not null auto_increment,
    advertiser varchar(255) default null,
    click_count int default null,
    created_at datetime default null,
    end_at datetime default null,
    image varchar(1024) default null,
    link varchar(1024) default null,
    price double default null,
    slot varchar(255) default null,
    start_at datetime default null,
    status varchar(255) default null,
    target_city varchar(255) default null,
    title varchar(255) default null,
    view_count int default null,
    merchant_id bigint default null,
    primary key (id)
) engine=innodb;

-- 插入广告数据


-- 3. 圈层成员表（circle_members）

drop table if exists circle_members;
create table circle_members (
    id bigint not null auto_increment,
    circle_id bigint default null,
    joined_at datetime default null,
    user_id bigint default null,
    primary key (id)
) engine=innodb;

-- 插入圈层成员数据


-- 4. 兴趣圈层表（circles）

drop table if exists circles;
create table circles (
    id bigint not null auto_increment,
    created_at datetime default null,
    creator_id bigint default null,
    description text,
    icon varchar(255) default null,
    member_count int default null,
    name varchar(255) default null,
    theme varchar(255) default null,
    primary key (id)
) engine=innodb;

-- 插入兴趣圈层数据


-- 5. 帖子评论表（comments）

drop table if exists comments;
create table comments (
    id bigint not null auto_increment,
    content text,
    created_at datetime default null,
    post_id bigint default null,
    user_id bigint default null,
    primary key (id)
) engine=innodb;

-- 插入帖子评论数据


-- 6. 数据采集批次表（crawl_batches）

drop table if exists crawl_batches;
create table crawl_batches (
    id bigint not null auto_increment,
    batch_no varchar(32) default null,
    detail text,
    duration_ms bigint default null,
    failed int default null,
    fallback_count int default null,
    fetched int default null,
    finished_at datetime default null,
    inserted int default null,
    message text,
    provider_total int default null,
    real_count int default null,
    started_at datetime default null,
    status varchar(16) default null,
    trigger_type varchar(16) default null,
    updated int default null,
    primary key (id)
) engine=innodb;

-- 插入数据采集批次数据


-- 7. 信用分记录表（credit_logs）

drop table if exists credit_logs;
create table credit_logs (
    id bigint not null auto_increment,
    created_at datetime default null,
    delta int default null,
    reason text,
    user_id bigint default null,
    primary key (id)
) engine=innodb;

-- 8. 动态行程表（dynamic_plans）

drop table if exists dynamic_plans;
create table dynamic_plans (
    id bigint not null auto_increment,
    adjust_factor varchar(255) default null,
    created_at datetime default null,
    days int default null,
    destination varchar(255) default null,
    new_plan_json text,
    old_plan_json text,
    reasons_json text,
    route_id bigint default null,
    trip_id bigint default null,
    user_id bigint default null,
    primary key (id)
) engine=innodb;

-- 插入动态行程数据


-- 9. 紧急联系人表（emergency_contacts）

drop table if exists emergency_contacts;
create table emergency_contacts (
    id bigint not null auto_increment,
    authorized bit(1) default null,
    created_at datetime default null,
    name varchar(255) default null,
    phone varchar(255) default null,
    relation varchar(255) default null,
    user_id bigint default null,
    primary key (id)
) engine=innodb;

-- 插入紧急联系人数据


-- 10. 行程花费记录表（expenses）

drop table if exists expenses;
create table expenses (
    id bigint not null auto_increment,
    amount double default null,
    category varchar(255) default null,
    created_at datetime default null,
    created_by bigint default null,
    per_person double default null,
    remark varchar(500) default null,
    scope varchar(255) default null,
    sharers varchar(1000) default null,
    title varchar(255) default null,
    trip_id bigint default null,
    user_id bigint default null,
    primary key (id)
) engine=innodb;

-- 插入行程花费记录数据


-- 11. 旅行足迹表（footprints）

drop table if exists footprints;
create table footprints (
    id bigint not null auto_increment,
    city varchar(255) default null,
    created_at datetime default null,
    lat double default null,
    lng double default null,
    name varchar(255) default null,
    note text,
    photo varchar(1024) default null,
    spot_id bigint default null,
    user_id bigint default null,
    visited_at date default null,
    primary key (id)
) engine=innodb;

-- 插入旅行足迹数据


-- 12. 导游预约订单表（guide_bookings）

drop table if exists guide_bookings;
create table guide_bookings (
    id bigint not null auto_increment,
    amount double default null,
    commission_rate double default null,
    created_at datetime default null,
    fee double default null,
    guide_id bigint default null,
    guide_income double default null,
    rating int default null,
    remark text,
    review_content text,
    reviewed_at datetime default null,
    service_id bigint default null,
    status varchar(255) default null,
    traveler_id bigint default null,
    trip_date date default null,
    settled bit(1) default null,
    settled_at datetime default null,
    primary key (id)
) engine=innodb;

-- 插入导游预约订单数据


-- 13. 导游档案表（guide_profiles）

drop table if exists guide_profiles;
create table guide_profiles (
    id bigint not null auto_increment,
    created_at datetime default null,
    intro text,
    order_count int default null,
    rating_avg double default null,
    rating_count int default null,
    status varchar(255) default null,
    themes varchar(255) default null,
    user_id bigint default null,
    supply_tier varchar(255) default null comment '供给层级：campus/city/agency',
    primary key (id)
) engine=innodb;

-- 插入导游档案数据


-- 14. 导游服务项目表（guide_services）

drop table if exists guide_services;
create table guide_services (
    id bigint not null auto_increment,
    created_at datetime default null,
    destination varchar(255) default null,
    guide_id bigint default null,
    intro text,
    price double default null,
    schedule varchar(255) default null,
    status varchar(255) default null,
    themes varchar(255) default null,
    title varchar(255) default null,
    primary key (id)
) engine=innodb;

-- 插入导游服务项目数据


-- 15. 保险保单表（insurance_policies）

drop table if exists insurance_policies;
create table insurance_policies (
    id bigint not null auto_increment,
