    recommend_score int default null,
    acquaintance int default null,
    dims_json text,
    source varchar(255) default null,
    created_at datetime default null,
    primary key (id),
    key idx_people_matches_user (user_id)
) engine=innodb;

-- 插入结伴匹配结果数据


