    title varchar(255) default null,
    trusted_badge bit(1) default null,
    type varchar(255) default null,
    view_count int default null,
    cost_per_person double default null comment '人均花费（元）',
    days int default null comment '建议游玩天数',
    avoid_tags varchar(255) default null comment '避坑标签 code（csv）',
    suitable_for varchar(255) default null comment '适合人群 code（csv）',
    primary key (id)
) engine=innodb;

